INSERT INTO "ops" VALUES('add','elementwise','linalg.generic(arith.addf)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 x + y','PyTorch 출력과 RNGD 시뮬레이터 출력이 오차 1e-4 이내로 일치.','두 출력이 오차 1e-4를 초과. 변환 규칙 또는 생성된 커널 코드 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_binary(AddF) → widen_concat');
INSERT INTO "ops" VALUES('sub','elementwise','linalg.generic(arith.subf)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 x - y','PyTorch 출력과 RNGD 시뮬레이터 출력이 오차 1e-4 이내로 일치.','두 출력이 오차 1e-4를 초과. 변환 규칙 또는 생성된 커널 코드 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_binary(SubF) → widen_concat');
INSERT INTO "ops" VALUES('mul','elementwise','linalg.generic(arith.mulf)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 x * y','PyTorch 출력과 RNGD 시뮬레이터 출력이 오차 1e-4 이내로 일치.','두 출력이 오차 1e-4를 초과. 변환 규칙 또는 생성된 커널 코드 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_binary(MulF) → widen_concat');
INSERT INTO "ops" VALUES('div','elementwise','linalg.generic(arith.divf)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 x / y (분모는 0.5 이상으로 생성, 0 근처 회피)','PyTorch 출력과 RNGD 시뮬레이터 출력이 오차 1e-4 이내로 일치.','두 출력이 오차 1e-4를 초과. 변환 규칙 또는 생성된 커널 코드 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_binary(DivF) → widen_concat');
INSERT INTO "ops" VALUES('rsqrt','elementwise','linalg.generic(math.rsqrt)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 rsqrt(x) = 1/sqrt(x) (x는 0.5~1.5 범위로 생성, 정의역 보장)','PyTorch 출력과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. 하드웨어에 Rsqrt가 직접 없어 Sqrt+나누기 조합으로 구현했는데도 정확함을 확인.','오차가 허용 범위를 초과. Sqrt+1.0나누기 조합 로직 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_unary(Sqrt) → vector_fp_div_with_mode(Mode10, 1.0) → widen_concat. 단항(입력 텐서 1개) 연산을 처음 지원하는 케이스.');
INSERT INTO "ops" VALUES('sqrt','elementwise','linalg.generic(math.sqrt)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 sqrt(x) (x는 0.5~1.5 범위로 생성, 정의역 보장)','PyTorch 출력과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. FpUnaryOp::Sqrt 단독으로 구현.','오차가 허용 범위를 초과. Sqrt 커널 로직 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_unary(Sqrt) → widen_concat. rsqrt와 달리 역수 없이 Sqrt 단독.');
INSERT INTO "ops" VALUES('exp','elementwise','linalg.generic(math.exp)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 exp(x) (x는 -2~2 범위 정규분포)','PyTorch 출력과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. FpUnaryOp::Exp 단독으로 구현.','오차가 허용 범위를 초과. Exp 커널 로직 확인 필요.','생성된 커널 체인: narrow_split → vector_fp_unary(Exp) → widen_concat. sqrt와 동일한 구조.');
INSERT INTO "ops" VALUES('sigmoid','elementwise','linalg.generic(arith.negf+math.exp+arith.addf+arith.divf)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 sigmoid(x) = 1/(1+exp(-x))','PyTorch 출력과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. FpUnaryOp::Sigmoid 단독으로 구현. negf+exp+addf+divf 복합 패턴을 단일 하드웨어 op으로 대체.','오차가 허용 범위를 초과. Sigmoid 커널 로직 확인 필요.','SiLU(x) = x*sigmoid(x)의 sigmoid 부분. 복합 linalg.generic 블록을 FpUnaryOp::Sigmoid 단독으로 교체.');
INSERT INTO "ops" VALUES('tanh','elementwise','linalg.generic(math.tanh)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 tanh(x)','FpUnaryOp::Tanh 단독 구현 — PASS','오차 초과','sqrt/exp와 동일한 단항 unary 패턴');
INSERT INTO "ops" VALUES('sin','elementwise','linalg.generic(math.sin)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 sin(x)','FpUnaryOp::Sin 단독 구현 — PASS','오차 초과','sqrt/exp와 동일한 단항 unary 패턴');
INSERT INTO "ops" VALUES('cos','elementwise','linalg.generic(math.cos)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 cos(x)','FpUnaryOp::Cos 단독 구현 — PASS','오차 초과','sqrt/exp와 동일한 단항 unary 패턴');
INSERT INTO "ops" VALUES('pow2','elementwise','linalg.generic(math.powf, 지수=2.0)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch가 계산한 x^2 (지수가 정확히 2.0인지 IR에서 실제 값 검증 후 매치)','PyTorch 출력과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. 하드웨어에 Pow가 직접 없어 MulF(x,x)로 구현했는데도 정확함을 확인.','오차가 허용 범위를 초과. 자기 자신을 VRF로 적재하는 로직 확인 필요.','생성된 커널: 같은 입력을 메인 스트림 + VRF로 두 번 적재 → vector_fp_binary(MulF, self_vrf). RMSNorm의 variance=mean(x^2) 계산에 필요한 첫 조각.');
INSERT INTO "ops" VALUES('batch_gemm','contraction','linalg.batch_matmul','rngd.batch_gemm','bf16','abs<=0.5, rel<=5% (contraction)',0,'done','bf16 양자화 입력 기준 PyTorch 계산값 (원본 f32 결과 아님)','bf16 양자화 입력 기준, PyTorch 계산값과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. 잔차는 bf16 반올림 범위.','오차가 bf16 반올림 범위를 초과. 행렬곱 커널 로직 결함 가능성.','생성된 커널: TRF 적재 → contract_outer → contract_packet → contract_time → contract_lane');
INSERT INTO "ops" VALUES('gemm','contraction','linalg.matmul','rngd.gemm','bf16','abs<=0.5, rel<=5% (contraction)',0,'done','bf16 양자화 입력 기준 PyTorch 계산값 (원본 f32 결과 아님)','bf16 양자화 입력 기준, PyTorch 계산값과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. 잔차는 bf16 반올림 범위.','오차가 bf16 반올림 범위를 초과. 행렬곱 커널 로직 결함 가능성.','batch_gemm과 동일 커널 구조를 V=1로 재사용 (TRF 적재 → contract_outer/packet/time/lane)');
INSERT INTO "ops" VALUES('dot_product','contraction','linalg.dot','rngd.dot_product','bf16','abs<=0.5, rel<=5% (contraction)',0,'done','bf16 양자화 입력 기준 PyTorch 계산값 (원본 f32 결과 아님)','bf16 양자화 입력 기준, PyTorch 계산값과 RNGD 시뮬레이터 출력이 허용 오차 이내로 일치. 잔차는 bf16 반올림 범위.','오차가 bf16 반올림 범위를 초과. 내적 커널 로직 결함 가능성.','batch_gemm과는 별도의 전용 커널 구조 사용 (M=1,N=1 degenerate case가 하드웨어 제약(Time::SIZE가 Lane::SIZE(8)로 안 나눠짐)에 걸려 재사용 불가). 고정 2048 버퍼 + 벡터 전체 reduction 방식.');
INSERT INTO "ops" VALUES('gemv','contraction','linalg.matvec','rngd.gemv','bf16','abs<=0.5, rel<=5% (contraction)',0,'done','PyTorch torch.mv(A, x) — A:[256,2048] bf16, x:[2048] bf16','gemv_kernel.rs 구조(Contraction Engine) 그대로 재사용. PASS','오차 초과. gemv 커널 로직 확인 필요.','I=256, J=2048. dot_product와 동일한 Contraction Engine 패턴. linalg.matvec → rngd.gemv.');
INSERT INTO "ops" VALUES('log','elementwise','linalg.generic(math.log)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch torch.log(x.abs().clamp(min=1e-6)) — [A=2048] f32','FpUnaryOp::Log 사용. 입력은 양수(abs+clamp) 필수. PASS','NaN 발생 시 입력에 음수 포함 — abs().clamp(min=1e-6) 적용 필요.','log(x): x > 0 필수. 음수 입력 시 NaN. e2e_pipeline.py에서 clamp 패턴 감지 필요.');
INSERT INTO "ops" VALUES('gelu','elementwise','linalg.generic(pow+mul+add+tanh+mul)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'planned','PyTorch F.gelu(x) — [A=2048] f32','3패스: x³*0.044715 → (x+x³c)*√(2/π)→tanh → (1+tanh)*0.5*x. PASS','오차 초과 시 패스별 누적 오차 확인. 5% 허용.','GELU 3패스. MulF ALU 3개 제한(Mul0/Mul1/Fma)으로 단일 파이프라인 불가. 누적 f32 오차 최대 3%.');
INSERT INTO "ops" VALUES('silu','elementwise','linalg.generic(sigmoid+mul)','rngd.elementwise','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','PyTorch F.silu(x) — [A=2048] f32','stash에 x 저장 → FpUnaryOp::Sigmoid → MulF(Stash). PASS','오차 초과 시 sigmoid 정밀도 확인 필요.','SiLU(x) = x * sigmoid(x). stash × mainstream 패턴으로 구현.');
INSERT INTO "ops" VALUES('transpose','layout','linalg.generic(identity)','rngd.transpose','f32','abs<=0.0, rel<=0% (layout)',0,'done','PyTorch x.t() — [M=2, N=8] f32','Transpose Engine 직접 사용. Slice=1 고정, Time=M, Packet=N으로 처리. PASS','오차 초과 또는 shape 불일치.','verify_transpose::<f32, B, C#8, C, B#8> 패턴 (M=B=2, N=C=8). commit 후 DmTensor[N,M] → to_hbm.');
INSERT INTO "ops" VALUES('reduce_sum','reduce','linalg.generic (reduction+addf)','rngd.reduce(op="sum")','f32','abs<=0.001, rel<=1% (reduce)',0,'done','reduction 축 합산값 기준 PyTorch 계산값','reduce_sum이 PyTorch 기준값과 일치. 트리 우회(elementwise add ×4) 또는 vector_inter_slice_reduce로 실행.','reduce_sum 결과 불일치. 트리 구조 또는 누적 순서 확인 필요.','IR: iterator_types에 reduction 포함 + body arith.addf 감지. 커널: vector_inter_slice_reduce 공식 API는 Unconsumed Padding(A%8) 에러로 사용 불가. 우회 구현: pilot_golden_add_a8_kernel을 4단계 트리 구조로 반복 — add([a0..a3],[a4..a7]) → add([s0,s1],[s2,s3]) → add([t0],[t1]). 생성된 커널 체인: narrow_split → vector_fp_binary(AddF) → widen_concat (×4단계). 오차 0 검증 완료. 1 flit = 32bytes = f32×8, A<8 커널 불가 제약.');
INSERT INTO "ops" VALUES('reduce_max','reduce','linalg.generic (reduction+maximumf)','rngd.reduce(op="max")','f32','abs<=0.001, rel<=1% (reduce)',0,'done','reduction 축 최대값 기준 PyTorch 계산값','reduce_max가 PyTorch 기준값과 일치. Softmax 수치 안정성용.','reduce_max 결과 불일치.','IR: iterator_types에 reduction 포함 + body arith.maximumf/maxf 감지. Softmax 수치 안정성용 max(scores) 연산. 커널: reduce_sum과 동일한 트리 우회 구조 적용 가능 — vector_fp_binary(MaxF)를 4단계 트리로 반복. 생성된 커널 체인: narrow_split → vector_fp_binary(MaxF) → widen_concat (×4단계).');
INSERT INTO "ops" VALUES('broadcast','layout','linalg.generic (identity, same shape)','rngd.broadcast','f32','abs<=0.0, rel<=0% (layout)',0,'done','데이터 복사 없이 indexing_maps만 변경','broadcast 변환 성공. 실제 계산 없이 메타데이터만 변경.','broadcast 변환 실패.','IR: identity body(linalg.yield %arg1) + 입출력 shape 동일 + indexing_maps 상이. 2nd pass에서 변환 (1st pass contraction chain 흡수 이후 실행, 순서 중요). vISA: DM(Data Mover) 주소 매핑 변경으로 처리. 실제 데이터 복사 불필요 — broadcast 축에서 동일 HBM 주소를 반복 읽기. 발생 위치: RMSNorm rsqrt 결과 broadcast [1,8,64]→[1,8,64] (indexing_maps만 변경).');
INSERT INTO "ops" VALUES('negf','elementwise','arith.negf / linalg.generic(arith.negf)','rngd.elementwise(negf)','f32','abs<=0.001, rel<=1% (elementwise)',0,'done','f32 부호 반전 기준 PyTorch 계산값','부호 반전이 PyTorch 기준값과 일치.','부호 반전 불일치.','RoPE rotate_half의 -x2 연산. arith.negf 단독 또는 linalg.generic(negf body) 형태로 출현. mul(-1.0) 또는 fp_unary(Neg)로 NPU 실행 가능.');
INSERT INTO "ops" VALUES('erf','elementwise','linalg.generic(math.erf)','rngd.elementwise','f32','1e-4',0,'done',NULL,NULL,NULL,NULL);
